examples.code:
if (has_totag()) {
        if(topology_hiding_match())
        {
                xlog("Found a request $rm belonging to an existing topology hiding dialog\n");
                route(relay);
                exit;
        }
}

if (has_totag()) {
    if (!topology_hiding_match() ) {
        xlog(" cannot match request to a dialog \n");
        send_reply(404,"Not found");
    } else
        route(RELAY);
}

